  -- ord 270: ca-cal-osha-trench-and-confined-3 -> sp-ca-confined-air-1
  update pb_ai.kb_chunks set lib = 'field', chunk = $kb${"id": "sp-ca-confined-air-1", "state": "CA", "tier": "core", "supersedes": "ca-cal-osha-trench-and-confined-3", "title": "California confined space air limits: Cal/OSHA CO 25 ppm and H2S 10 / 15 / 50 ppm (8 CCR 5155), stricter than federal", "topic": "State safety plan: confined space", "text": "California's permissible exposure limits (Title 8 section 5155, Table AC-1) are stricter than federal for gases crews meet in manholes and vaults. Carbon monoxide: Cal/OSHA PEL 25 ppm 8-hour average with a 200 ppm ceiling (federal construction PEL 50 ppm; NIOSH REL 35 ppm, which many monitors use as the alarm). Hydrogen sulfide: Cal/OSHA 10 ppm 8-hour average, 15 ppm short-term (15-minute) limit, and a 50 ppm ceiling never to be exceeded; federal construction 10 ppm. Carbon dioxide: 5,000 ppm PEL, 30,000 ppm STEL. The confined space limits are the same in both systems: oxygen 19.5 to 23.5 percent and 10 percent of the LEL. The app's permit defaults (O2 19.5-23.5, LEL 10, H2S 10, CO 25) already use this CO limit everywhere; a company program may set stricter limits, and 15 ppm H2S is a 15-minute limit, not a working level. None of this is a go/no-go: the entry supervisor and the company program decide.", "source": "8 CCR 5155 Table AC-1 (carbon monoxide, hydrogen sulfide, carbon dioxide rows); 29 CFR 1926.55 Appendix A; NIOSH Pocket Guide", "url": "https://www.dir.ca.gov/Title8/5155.html", "checked": "2026-11-20", "edition": "Title 8 section 5155 as posted on dir.ca.gov", "confidence": "high", "kind": "summary", "license": "gov-state", "note": "Same facts as ca-cal-osha-trench-and-confined-3 (this ord), now a CA state card (state field, title starts with the state)."}$kb$::jsonb
   where version = 'b3e91f6c47d2' and ord = 270 and chunk->>'id' = $kb$ca-cal-osha-trench-and-confined-3$kb$ and md5(chunk::text) = md5($kb${"id": "ca-cal-osha-trench-and-confined-3", "url": "https://www.dir.ca.gov/Title8/5155.html", "text": "California's permissible exposure limits (Title 8 section 5155, Table AC-1) are stricter than federal for gases crews meet. Carbon monoxide: Cal/OSHA PEL 25 ppm 8-hour average with a 200 ppm ceiling (federal construction PEL 50 ppm; NIOSH REL 35 ppm, which many monitors use as the alarm). Hydrogen sulfide: Cal/OSHA 10 ppm 8-hour average, 15 ppm short-term (15-minute) limit, and a 50 ppm ceiling never to be exceeded; federal construction 10 ppm. Carbon dioxide: 5,000 ppm PEL, 30,000 ppm STEL. The confined space limits are the same in both systems: oxygen 19.5 to 23.5 percent and 10 percent of the LEL. The app's permit defaults (O2 19.5-23.5, LEL 10, H2S 10, CO 25) already use the Cal/OSHA CO limit everywhere; a company program may set stricter limits, and 15 ppm H2S is a 15-minute limit, not a working level. None of this is a go/no-go: the entry supervisor and the company program decide.", "title": "Cal/OSHA exposure limits that differ from federal: CO 25 ppm, H2S 10/15 ppm (8 CCR 5155)", "topic": "Cal/OSHA (Title 8) rules for trenches and confined spaces in California", "source": "8 CCR 5155 Table AC-1 (carbon monoxide, hydrogen sulfide, carbon dioxide rows); 29 CFR 1926.55 Appendix A; NIOSH Pocket Guide", "confidence": "high"}$kb$::jsonb::text);
