  -- ord 2833: sp-wa-confined-1 (edited in place)
  update pb_ai.kb_chunks set lib = 'field', chunk = $kb${"id": "sp-wa-confined-1", "state": "WA", "tier": "core", "supersedes": "sp-wa-confined-1", "title": "Washington confined space rule (chapter 296-809 WAC): one rule for all industries", "topic": "State safety plan: confined space", "text": "Washington has one confined space rule for all industries, chapter 296-809 WAC, instead of the federal construction rule; OSHA's adoption table lists it as different but at least as effective. Air numbers match federal: flammables over 10 percent of the LFL or LEL, oxygen below 19.5 or above 23.5 percent (296-809-099). Its definitions add: any physical hazard (electrical shock, moving parts) makes a space permit-required; where the opening is big enough to fully enter, a permit is needed even for partial body entry; excavations and pits are among its examples. Permit (read 2026-11-19): the same 15 items as the federal general industry list, in another order (296-809-50004), with equipment to detect a rise in hazard if ventilation stops (federal construction item (e)); available at entry (50002(5)); problems noted on it (50002(7)); kept 1 year (50006(2)). Air is tested with a calibrated, direct-reading instrument (60004(3)(a)). The app's permit form covers these items.", "source": "WAC 296-809-099 (WSR 18-02-071, eff. 2/5/18), 296-809-50002, 296-809-50004, 296-809-50006, 296-809-60004", "url": "https://lawfilesext.leg.wa.gov/Law/WACArchive/2024/htm/WAC%20296%20-809%20%20CHAPTER/WAC%20296%20-809%20-099.htm", "checked": "2026-11-21", "edition": "Chapter 296-809 WAC: permit sections read 2026-11-19; 296-809-099 as archived 2024, read 2026-11-21", "confidence": "medium", "kind": "summary", "license": "gov-state", "note": "Adds the 296-809-099 definitions (read 2026-11-21). \"Not re-read on 2026-11-20\" replaced by the dates in edition."}$kb$::jsonb
   where version = 'b3e91f6c47d2' and ord = 2833 and chunk->>'id' = $kb$sp-wa-confined-1$kb$ and md5(chunk::text) = md5($kb${"id": "sp-wa-confined-1", "url": "https://www.law.cornell.edu/regulations/washington/WAC-296-809-50004", "kind": "summary", "text": "Washington has one confined space rule for all industries, chapter 296-809 WAC, instead of adopting the federal construction rule. As read on November 19, 2026: the permit carries the same 15 items as the federal general industry list, in a different order (WAC 296-809-50004), and the testing-equipment item names equipment able to detect a rise in atmospheric hazard if ventilation stops, which is federal construction item (e). The permit is available at entry (296-809-50002(5)), problems met during entry are noted on it (50002(7)), and it is kept 1 year (50006(2)). Air is tested with a calibrated, direct-reading instrument (296-809-60004(3)(a)). OSHA's adoption table lists this state's rule as different from the federal construction rule but at least as effective. The app's permit form covers these items. The chapter was not re-read on 2026-11-20.", "tier": "core", "state": "WA", "title": "Washington confined space rule (chapter 296-809 WAC)", "topic": "State safety plan: confined space", "source": "WAC 296-809-50002, 296-809-50004, 296-809-50006, 296-809-60004", "checked": "2026-11-20", "edition": "Chapter 296-809 WAC, read 2026-11-19", "license": "gov-state", "confidence": "medium", "supersedes": "plan-wa-confined-1"}$kb$::jsonb::text);
  get diagnostics vk = row_count; if vk <> 1 then raise exception 'FAIL: row % is not the expected live text', 2833; end if;
  -- ord 2922: osha-pl-cs-scope-1 (edited in place)
  update pb_ai.kb_chunks set lib = 'field', chunk = $kb${"id": "osha-pl-cs-scope-1", "state": "US", "tier": "core", "supersedes": "osha-pl-cs-scope-1", "title": "When the construction confined space rule applies, and when it does not", "topic": "Confined space rules (OSHA Subpart AA)", "text": "29 CFR 1926 Subpart AA (1926.1201 to 1926.1213, in effect since August 3, 2015) protects employees doing construction work at a site with one or more confined spaces. The rule's own examples include manholes, sewers, storm drains, pits, vaults, tanks, lift stations and pipe; on utility jobs manholes, vaults, wet wells and large pipes are typically confined spaces, and sewer manholes are usually permit spaces because of hydrogen sulfide, methane and low oxygen. It does not apply to construction work regulated by Subpart P (excavations), Subpart S (underground construction, caissons, cofferdams and compressed air) or Subpart Y (diving) (1926.1201(b)). So an open trench is under the excavation rule, but a manhole, a vault or the inside of a pipe is a confined space even when it sits in an excavation. Where another OSHA rule also covers a hazard in the space, follow both (1926.1201(c)). Maintenance work that is not construction is under the general industry rule, 29 CFR 1910.146. Before any entry use the company's written program and the app's confined space permit. A state with its own OSHA plan may have its own rule: see the confined space state tables.", "source": "29 CFR 1926.1201(a)-(c); OSHA Confined Spaces in Construction FAQ", "url": "https://www.ecfr.gov/current/title-29/subtitle-B/chapter-XVII/part-1926/subpart-AA", "checked": "2026-11-20", "edition": "eCFR current text, read 2026-11-20", "confidence": "high", "kind": "summary", "license": "gov-us", "note": "Takes in confined-space-silica-1 (retired: the plain overview; its program items are in osha-pl-cs-first-steps-1 / -program-1)."}$kb$::jsonb
   where version = 'b3e91f6c47d2' and ord = 2922 and chunk->>'id' = $kb$osha-pl-cs-scope-1$kb$ and md5(chunk::text) = md5($kb${"id": "osha-pl-cs-scope-1", "url": "https://www.ecfr.gov/current/title-29/subtitle-B/chapter-XVII/part-1926/subpart-AA", "kind": "summary", "text": "29 CFR 1926 Subpart AA (1926.1201 to 1926.1213, in effect since August 3, 2015) protects employees doing construction work at a site with one or more confined spaces. The rule's own examples include manholes, sewers, storm drains, pits, vaults, tanks, lift stations and pipe. It does not apply to construction work regulated by Subpart P (excavations), Subpart S (underground construction, caissons, cofferdams and compressed air) or Subpart Y (diving) (1926.1201(b)). So an open trench is under the excavation rule, but a manhole, a vault or the inside of a pipe is a confined space even when it sits in an excavation. Where another OSHA rule also covers a hazard in the space, follow both (1926.1201(c)). Maintenance work that is not construction is under the general industry rule, 29 CFR 1910.146.", "tier": "core", "state": "US", "title": "When the construction confined space rule applies, and when it does not", "topic": "Confined space rules (OSHA Subpart AA)", "source": "29 CFR 1926.1201(a)-(c); OSHA Confined Spaces in Construction FAQ", "checked": "2026-11-20", "edition": "eCFR current text, read 2026-11-20", "license": "gov-us", "confidence": "high"}$kb$::jsonb::text);
  get diagnostics vk = row_count; if vk <> 1 then raise exception 'FAIL: row % is not the expected live text', 2922; end if;
  -- ord 2925: osha-pl-cs-altproc-1 (edited in place)
  update pb_ai.kb_chunks set lib = 'field', chunk = $kb${"id": "osha-pl-cs-altproc-1", "state": "US", "tier": "core", "supersedes": "osha-pl-cs-altproc-1", "title": "Alternate procedures: ventilation-only entry into a permit space, and when it is not allowed", "topic": "Confined space rules (OSHA Subpart AA)", "text": "29 CFR 1926.1203(e)(1): alternate procedures (no full permit) only when the employer shows all physical hazards are eliminated or isolated so the only hazard is the atmosphere, and continuous forced air ventilation alone keeps the space safe, backed by documented monitoring data available to entrants; an entry to get that data is a full permit entry. (e)(2): make it safe to open the cover and guard the opening; test before entry \"for oxygen content, for flammable gases and vapors, and for potential toxic air contaminants, in that order\"; no hazardous atmosphere while anyone is inside; forced air at the work area from a clean source, from before entry until all are out; continuous monitoring (periodic only under the exception); all out at once on a hazard; safe access; a written certification (date, location, signature) at the entrance. Any engulfment, machinery, electrical or other physical hazard, such as sewer flow that can surge, means a full permit. The entry supervisor and the company program decide; Ask does not.", "source": "29 CFR 1926.1203(e)(1)-(2)", "url": "https://www.ecfr.gov/current/title-29/subtitle-B/chapter-XVII/part-1926/subpart-AA", "checked": "2026-11-20", "edition": "eCFR current text, read 2026-11-20", "confidence": "high", "kind": "summary", "license": "gov-us", "note": "Takes in confined-space-field-numbers-6 (retired). The reclassification sentence moved to osha-pl-cs-reclass-1."}$kb$::jsonb
   where version = 'b3e91f6c47d2' and ord = 2925 and chunk->>'id' = $kb$osha-pl-cs-altproc-1$kb$ and md5(chunk::text) = md5($kb${"id": "osha-pl-cs-altproc-1", "url": "https://www.ecfr.gov/current/title-29/subtitle-B/chapter-XVII/part-1926/subpart-AA", "kind": "summary", "text": "29 CFR 1926.1203(e)(1): an employer may use the shorter alternate procedures only when it can show that all physical hazards in the space are eliminated or isolated through engineering controls so the only hazard is an actual or potential hazardous atmosphere, and that continuous forced air ventilation alone is enough to keep the space safe, backed by monitoring data, with the determination written down and available to each entrant. (e)(2) Then: make it safe to remove the cover; guard the opening at once; test the air before entry \"with a calibrated direct-reading instrument, for oxygen content, for flammable gases and vapors, and for potential toxic air contaminants, in that order\"; no hazardous atmosphere while anyone is inside; continuous forced air ventilation; continuous monitoring; get out at once if a hazard shows up; a safe way in and out; and a written certification with the date, the location and the signature of the person certifying. (g) A permit space may be reclassified as non-permit only when a competent person finds no atmospheric hazard and every other hazard eliminated or isolated without entry, and documents it.", "tier": "core", "state": "US", "title": "Alternate procedures and reclassifying a permit space", "topic": "Confined space rules (OSHA Subpart AA)", "source": "29 CFR 1926.1203(e)(1)-(2), (g)", "checked": "2026-11-20", "edition": "eCFR current text, read 2026-11-20", "license": "gov-us", "confidence": "high"}$kb$::jsonb::text);
  get diagnostics vk = row_count; if vk <> 1 then raise exception 'FAIL: row % is not the expected live text', 2925; end if;
  -- ord 2928: osha-pl-cs-monitor-1 (edited in place)
  update pb_ai.kb_chunks set lib = 'field', chunk = $kb${"id": "osha-pl-cs-monitor-1", "state": "US", "tier": "core", "supersedes": "osha-pl-cs-monitor-1", "title": "Working in a live sewer that could flood: OSHA early-warning system, air testing order, continuous monitoring", "topic": "Confined space rules (OSHA Subpart AA)", "text": "29 CFR 1926.1204(e). Test from outside before entry with a calibrated, bump-tested direct-reading meter, in this order: \"oxygen first, then combustible gases and vapors, then toxic gases and vapors\" ((e)(3); the LEL sensor needs oxygen to read right; 1910.146(d)(5)(iii) is the same). Test top, middle and bottom: H2S and CO2 settle low, methane rises. Then monitor continuously where entrants work, or periodically if continuous equipment is not commercially available or periodic is shown to be enough ((e)(2)). Ventilate with fresh air; get out at once on an alarm. Entrants may watch the testing, get a re-test on request and get the results right away ((e)(4) to (e)(6)). A sewer that cannot be isolated: test to the extent feasible and use an early-warning system that watches for engulfment and alerts entrants and attendants in time to get out ((e)(1)). Log readings on the permit at its interval; the app blocks check-in until a fresh good test is logged.", "source": "29 CFR 1926.1204(e)(1)-(6); 1926.1202; 1910.146(d)(5)", "url": "https://www.law.cornell.edu/cfr/text/29/1926.1204", "checked": "2026-11-20", "edition": "eCFR current text, read 2026-11-20", "confidence": "high", "kind": "summary", "license": "gov-us", "note": "Takes in confined-space-field-numbers-2 and confined-space-silica-2 (retired). The state test-order cite (8 CCR 1953(a)(5)) is in sp-ca-confined-1."}$kb$::jsonb
   where version = 'b3e91f6c47d2' and ord = 2928 and chunk->>'id' = $kb$osha-pl-cs-monitor-1$kb$ and md5(chunk::text) = md5($kb${"id": "osha-pl-cs-monitor-1", "url": "https://www.law.cornell.edu/cfr/text/29/1926.1204", "kind": "summary", "text": "29 CFR 1926.1204(e). Test before entry is authorized. Test in this order: \"oxygen first, then combustible gases and vapors, then toxic gases and vapors.\" Then monitor continuously where entrants are working, unless the employer can show continuous monitoring equipment is not commercially available or periodic monitoring is enough; then monitor periodically, often enough to be sure conditions stay acceptable. Give entrants or their representative the chance to watch the testing, re-test in front of any entrant who asks because the first test may have been inadequate, and give them the results right away. Where an engulfment hazard cannot be isolated, such as a sewer that can flood, provide an early-warning system that continuously watches for the hazard and alerts entrants and attendants in time to get out. Limits: oxygen 19.5 to 23.5 percent, flammables at or under 10 percent of the LFL. Hydrogen sulfide and carbon monoxide limits come from the exposure limit tables, not from Subpart AA.", "tier": "core", "state": "US", "title": "Working in a live sewer that could flood: OSHA early-warning system, air testing order, continuous monitoring", "topic": "Confined space rules (OSHA Subpart AA)", "source": "29 CFR 1926.1204(e)(1)-(6); 1926.1202", "checked": "2026-11-20", "edition": "eCFR current text, read 2026-11-20", "license": "gov-us", "confidence": "high"}$kb$::jsonb::text);
  get diagnostics vk = row_count; if vk <> 1 then raise exception 'FAIL: row % is not the expected live text', 2928; end if;
  -- ord 2929: osha-pl-cs-permit-1 (edited in place)
  update pb_ai.kb_chunks set lib = 'field', chunk = $kb${"id": "osha-pl-cs-permit-1", "state": "US", "tier": "core", "supersedes": "osha-pl-cs-permit-1", "title": "The entry permit: the 16 items and how long to keep it", "topic": "Confined space rules (OSHA Subpart AA)", "text": "29 CFR 1926.1206 lists what the permit identifies: (a) the space; (b) the purpose of entry; (c) the date and authorized duration; (d) the entrants, by name or by a roster or tracking system; (e) how a rise in air hazard is detected if ventilation stops; (f) each attendant by name; (g) each entry supervisor by name, with the signature or initials of each supervisor who authorizes entry; (h) the hazards of the space; (i) the isolation and control measures; (j) the acceptable entry conditions; (k) test results with the tester's name or initials and when; (l) rescue and emergency services and how to summon them; (m) communication procedures; (n) equipment: PPE, testing, communications, alarms, rescue; (o) other information needed for safety; (p) other permits, such as hot work. The supervisor signs before entry and \"The entry employer must retain each canceled entry permit for at least 1 year\" (1926.1205(b), (f)); the permit process card has posting, duration, cancel or suspend and problems noted.", "source": "29 CFR 1926.1205(b), (f); 1926.1206(a)-(p)", "url": "https://www.law.cornell.edu/cfr/text/29/1926.1206", "checked": "2026-11-20", "edition": "eCFR current text, read 2026-11-20", "confidence": "high", "kind": "summary", "license": "gov-us", "note": "The 1926.1205 process sentences moved to osha-pl-cs-permit-keep-1."}$kb$::jsonb
   where version = 'b3e91f6c47d2' and ord = 2929 and chunk->>'id' = $kb$osha-pl-cs-permit-1$kb$ and md5(chunk::text) = md5($kb${"id": "osha-pl-cs-permit-1", "url": "https://www.law.cornell.edu/cfr/text/29/1926.1206", "kind": "summary", "text": "29 CFR 1926.1206 lists what the permit identifies: (a) the space; (b) the purpose of entry; (c) the date and authorized duration; (d) the entrants, by name or by a roster or tracking system; (e) how a rise in air hazard is detected if ventilation stops; (f) each attendant by name; (g) each entry supervisor by name, with the signature or initials of each supervisor who authorizes entry; (h) the hazards of the space; (i) the isolation and control measures; (j) the acceptable entry conditions; (k) test results with the tester's name or initials and when; (l) rescue and emergency services and how to summon them; (m) communication procedures; (n) equipment: PPE, testing, communications, alarms, rescue; (o) other information needed for safety; (p) other permits, such as hot work. 1926.1205: the supervisor signs before entry; the completed permit is available to entrants at entry, by posting at the portal or another equally effective way; the duration is no longer than the task needs; problems met during entry are noted on the permit; and \"The entry employer must retain each canceled entry permit for at least 1 year.\" A permit can be suspended instead of cancelled.", "tier": "core", "state": "US", "title": "The entry permit: the 16 items and how long to keep it", "topic": "Confined space rules (OSHA Subpart AA)", "source": "29 CFR 1926.1205(a)-(f); 1926.1206(a)-(p)", "checked": "2026-11-20", "edition": "eCFR current text, read 2026-11-20", "license": "gov-us", "confidence": "high"}$kb$::jsonb::text);
  get diagnostics vk = row_count; if vk <> 1 then raise exception 'FAIL: row % is not the expected live text', 2929; end if;
  -- ord 2932: osha-pl-cs-rescue-1 (edited in place)
  update pb_ai.kb_chunks set lib = 'field', chunk = $kb${"id": "osha-pl-cs-rescue-1", "state": "US", "tier": "core", "supersedes": "osha-pl-cs-rescue-1", "title": "Confined space rescue: rescue has to be arranged before entry; 911 alone is not a plan", "topic": "Confined space rules (OSHA Subpart AA)", "text": "29 CFR 1926.1211(a): an employer who names an outside rescue service (fire department, contract team) first evaluates whether it can respond in a timely manner for this space's hazards and can rescue from this type of space (a vertical manhole, a deep wet well); picks one that can; tells it the hazards; gives it access to plan and practice; and has it agree to say right away when it is unavailable. OSHA's Appendix F to 1910.146: posting the number or relying on 911 at the time of an emergency does not comply, so 911 is not a plan unless that service was evaluated and agreed. (b) An own rescue team: PPE, training, first aid and CPR (one member certified), a practice rescue every 12 months. (d) The SDS for any substance an injured entrant met goes to the medical facility. In practice: call the station before the job, confirm confined space rescue and response time, write it on the permit, keep retrieval set up, know the address and cross street (the app's EMERGENCY button shows a script). If they cannot respond in time, entry waits.", "source": "29 CFR 1926.1211(a), (b), (d); 1910.146 Appendix F", "url": "https://www.ecfr.gov/current/title-29/subtitle-B/chapter-XVII/part-1926/subpart-AA", "checked": "2026-11-21", "edition": "eCFR current text, read 2026-11-20", "confidence": "high", "kind": "summary", "license": "gov-us", "note": "Takes in confined-space-field-numbers-5 (retired). Retrieval detail moved to osha-pl-cs-retrieval-1; the state rescue section (8 CCR 1960) is in the state cards."}$kb$::jsonb
   where version = 'b3e91f6c47d2' and ord = 2932 and chunk->>'id' = $kb$osha-pl-cs-rescue-1$kb$ and md5(chunk::text) = md5($kb${"id": "osha-pl-cs-rescue-1", "url": "https://www.ecfr.gov/current/title-29/subtitle-B/chapter-XVII/part-1926/subpart-AA", "kind": "summary", "text": "29 CFR 1926.1211. (a) An employer who names a rescue service evaluates whether it can respond in time for the hazards and is able to do the rescue, picks one that can, tells it the hazards, gives it access to the spaces to plan and practice, and has it agree to notify the employer right away when it is unavailable. (b) An employer's own rescue team gets PPE and training, first aid and CPR with at least one member currently certified, and a practice rescue at least once every 12 months. (c) \"Non-entry rescue is required unless the retrieval equipment would increase the overall risk of entry or would not contribute to the rescue of the entrant.\" Each entrant wears a chest or full body harness with a retrieval line attached at the center of the back near shoulder level or above the head; the other end is attached to a mechanical device or fixed point outside so rescue can begin as soon as needed. \"A mechanical device must be available to retrieve personnel from vertical type permit spaces more than 5 feet (1.52 meters) deep.\" Calling 911 is not a rescue plan unless that service has been evaluated and has agreed.", "tier": "core", "state": "US", "title": "Confined space rescue: retrieval lines and rescue services", "topic": "Confined space rules (OSHA Subpart AA)", "source": "29 CFR 1926.1211(a)-(d)", "checked": "2026-11-20", "edition": "eCFR current text, read 2026-11-20", "license": "gov-us", "confidence": "high"}$kb$::jsonb::text);
