  -- ord 2977: sp-ca-confined-1 (edited in place)
  update pb_ai.kb_chunks set lib = 'field', chunk = $kb${"id": "sp-ca-confined-1", "state": "CA", "tier": "core", "supersedes": "sp-ca-confined-1", "title": "California confined space rule for construction (8 CCR 1950 to 1962, Article 37), not federal Subpart AA", "topic": "State safety plan: confined space", "text": "California's construction confined space rule is 8 CCR 1950 to 1962 (Article 37), in effect since December 30, 2015, amended January 1, 2026 (see the 2026 card). It mirrors federal Subpart AA: 1951 definitions, 1952 general requirements, 1953 program, 1954 permitting, 1955 permit, 1956 training, 1957 to 1959 entrant, attendant and supervisor duties, 1960 rescue. The 1955(a) permit items are the same 16 as 1926.1206; supervisor signs before entry (1954(b)), permit available at entry (1954(c)), kept 1 year (1954(f)). Test from outside: oxygen, flammable, toxic (1953(a)(5)(C)); monitor continuously unless periodic is shown enough (1953(a)(5)(B)); a sewer gets continuous monitoring and an engulfment early warning (1953(a)(5)(A)). Not for Article 6 excavations, tunnels, diving or pressurized work (1950(b)); its note lists manholes, sewers, tanks and vaults. Maintenance (not construction) is 8 CCR 5157; 5158 was the construction rule before 2015. CO and H2S limits are stricter than federal (air limits card).", "source": "8 CCR 1950(a)-(c), 1951-1960, 1953(a)(5), 1954, 1955; 8 CCR 5156(b), 5157, 5158", "url": "https://www.dir.ca.gov/Title8/1950.html", "checked": "2026-11-20", "edition": "Title 8 CCR Article 37 operative 12-30-2015 (Register 2016, No. 1); permit cites read 2026-11-19, 1950 read 2026-11-20", "effective": "2015-12-30", "confidence": "high", "kind": "summary", "license": "gov-state", "note": "Takes in ca-cal-osha-trench-and-confined-4 (retired: the same Article 37 summary) and the Cal/OSHA cites of the retired confined-space-field-numbers cards."}$kb$::jsonb
   where version = 'b3e91f6c47d2' and ord = 2977 and chunk->>'id' = $kb$sp-ca-confined-1$kb$ and md5(chunk::text) = md5($kb${"id": "sp-ca-confined-1", "url": "https://www.dir.ca.gov/Title8/1950.html", "kind": "summary", "text": "California's construction confined space rule is 8 CCR 1950 to 1962 (Construction Safety Orders, Article 37), in effect since December 30, 2015. It follows the federal rule, 29 CFR 1926 Subpart AA: the permit items in 8 CCR 1955(a) are the same 16 as federal 1926.1206, the supervisor signs before entry (1954(b)), the permit is available to entrants at entry (1954(c)) and cancelled permits are kept 1 year (1954(f)). It does not apply to work regulated by Article 6 (excavations), the Tunnel Safety Orders, diving operations, or pressurized worksite operations (1950(b)). Its own note lists manholes, sewers, tanks, vaults and similar spaces as examples. Work that is not construction, such as maintenance in an existing system, is under the general industry rule, 8 CCR 5157. Permit item citations come from the read of November 19, 2026; section 1950 was read again on November 20.", "tier": "core", "state": "CA", "title": "California confined space rule for construction (8 CCR 1950 to 1962)", "topic": "State safety plan: confined space", "source": "8 CCR 1950(a)-(c); 8 CCR 1954, 1955; 8 CCR 5157", "checked": "2026-11-20", "edition": "Title 8 CCR, Article 37 operative 12-30-2015 (Register 2016, No. 1)", "license": "gov-state", "effective": "2015-12-30", "confidence": "high"}$kb$::jsonb::text);
  get diagnostics vk = row_count; if vk <> 1 then raise exception 'FAIL: row % is not the expected live text', 2977; end if;
  -- ord 3016: sp-md-who-1 (edited in place)
  update pb_ai.kb_chunks set lib = 'field', chunk = $kb${"id": "sp-md-who-1", "url": "https://labor.maryland.gov/labor/mosh/moshspecific.shtml", "kind": "summary", "text": "Maryland's plan, MOSH, lists its state-specific regulations in COMAR Title 09, Subtitle 12: employee injury and illness records (09.12.21), fall protection in steel erection (09.12.25), crane safety (09.12.26), tower crane operator certification (09.12.27), tree care (09.12.28), heat stress (09.12.32), access to information on hazardous and toxic substances (09.12.33), field sanitation (09.12.36) and personnel platforms on cranes (09.12.38). The same MOSH page lists Maryland supplements to federal standards, including 29 CFR 1926.651 (excavations), 29 CFR 1926.1201 to 1213 (confined spaces in construction), 29 CFR 1926.62 (lead) and Subpart CC (cranes). The excavation amendments keep the federal 5 ft trench rule and add that protective system records (tabulated data, designs) are kept at the jobsite (see Maryland's trench card); MOSH adopted the federal confined space in construction rule by reference effective January 2, 2017 and repealed the old state rule (COMAR 09.12.35); the adoption page names no Maryland change, but the supplement's own text was not read (2026-11-21), so what it adds is not confirmed: ask MOSH.", "tier": "core", "state": "MD", "title": "Maryland: MOSH-specific rules and supplements to the federal trench rule", "topic": "State safety plan: who enforces and what differs", "source": "MOSH, Maryland-specific standards page; COMAR 09.12.21-09.12.38", "checked": "2026-11-20", "edition": "MOSH page, read 2026-11-20", "license": "gov-state", "confidence": "medium", "unconfirmed": "yes"}$kb$::jsonb
   where version = 'b3e91f6c47d2' and ord = 3016 and chunk->>'id' = $kb$sp-md-who-1$kb$ and md5(chunk::text) = md5($kb${"id": "sp-md-who-1", "url": "https://labor.maryland.gov/labor/mosh/moshspecific.shtml", "kind": "summary", "text": "Maryland's plan, MOSH, lists its state-specific regulations in COMAR Title 09, Subtitle 12: employee injury and illness records (09.12.21), fall protection in steel erection (09.12.25), crane safety (09.12.26), tower crane operator certification (09.12.27), tree care (09.12.28), heat stress (09.12.32), access to information on hazardous and toxic substances (09.12.33), field sanitation (09.12.36) and personnel platforms on cranes (09.12.38). The same MOSH page lists Maryland supplements to federal standards, including 29 CFR 1926.651 (excavations), 29 CFR 1926.1201 to 1213 (confined spaces in construction), 29 CFR 1926.62 (lead) and Subpart CC (cranes). The excavation amendments keep the federal 5 ft trench rule and add that protective system records (tabulated data, designs) are kept at the jobsite (see Maryland's trench card); the confined space supplement's text was not read on 2026-11-20, so what it adds is not confirmed: ask MOSH. The old state confined space rule (COMAR 09.12.35) was repealed effective January 2, 2017.", "tier": "core", "state": "MD", "title": "Maryland: MOSH-specific rules and supplements to the federal trench rule", "topic": "State safety plan: who enforces and what differs", "source": "MOSH, Maryland-specific standards page; COMAR 09.12.21-09.12.38", "checked": "2026-11-20", "edition": "MOSH page, read 2026-11-20", "license": "gov-state", "confidence": "medium", "unconfirmed": "yes"}$kb$::jsonb::text);
