  -- ord 3222: sp-ca-confined-2026-1 (edited in place)
  update pb_ai.kb_chunks set lib = 'field', chunk = $kb${"id": "sp-ca-confined-2026-1", "state": "CA", "tier": "core", "supersedes": "sp-ca-confined-2026-1", "title": "California confined space changes from January 1, 2026: site survey, testing, inerting and rescue at the site", "topic": "State safety plan: confined space", "text": "California amended 8 CCR 1951, 1952, 1953, 1955, 1956 and 1960 (and 5156) effective January 1, 2026 (filed November 4, 2025). Text approved by OAL (read 2026-11-21): a competent person must \"conduct an initial survey of its work area for confined spaces existing at the time work begins\" (1952(a)(1)) and inspect often enough to find new ones (1952(a)(2)); evaluation includes testing (1952(a)(4)); if flammables cannot be brought under 10 percent LFL, entry only after inerting, with PPE (1953(a)(3)(D)); the permit says how to summon rescue and emergency medical services (1955(a)(12)); and \"the rescue services at the site are trained, immediately available, properly equipped\" (1960(a)), with a note on a standby person able to rescue at once. Federal 1926.1211(a) accepts an evaluated service that can respond in a timely manner: follow California's stricter wording. Which words are new is not confirmed from the text (no underline); the Final Statement of Reasons (2025-09-18) shows no permit item change.", "source": "OSHSB rulemaking Confined Spaces in Construction: Text Approved by OAL; Final Statement of Reasons updated 2025-09-18; 8 CCR 1952, 1953, 1955, 1960", "url": "https://dir.ca.gov/OSHSB/documents/Confined-Spaces-in-Construction-OAL-Changes-Text.pdf", "checked": "2026-11-21", "edition": "Amendments effective 2026-01-01, filed 2025-11-04", "effective": "2026-01-01", "confidence": "medium", "kind": "summary", "license": "gov-state", "unconfirmed": "yes", "note": "Rewritten from the OAL-approved text (read 2026-11-21); keeps every fact of the FSOR-based card."}$kb$::jsonb
   where version = 'b3e91f6c47d2' and ord = 3222 and chunk->>'id' = $kb$sp-ca-confined-2026-1$kb$ and md5(chunk::text) = md5($kb${"id": "sp-ca-confined-2026-1", "url": "https://dir.ca.gov/OSHSB/Confined-Spaces-in-Construction.html", "kind": "summary", "text": "California amended its construction confined space rules (8 CCR 1951, 1952, 1953, 1955, 1956, 1960) effective January 1, 2026. Per the Standards Board's Final Statement of Reasons: a competent person surveys the work area for confined spaces that exist when work begins (1952(a)(1)) and inspects often enough to find new ones (1952(a)(2)); evaluation of a space now includes testing to tell a confined space from a permit space (1952(a)(4)); where less than 10 percent LFL cannot be reached the space is inerted and PPE provided (1953); and standby personnel trained, equipped and available to rescue an entrant are required (1960(a)). The Final Statement of Reasons describes no change to the permit items in 1955. Read the amended rule text before relying on wording.", "tier": "core", "state": "CA", "title": "California confined space changes from January 1, 2026: site survey and rescue standby", "topic": "State safety plan: confined space", "source": "OSHSB rulemaking Confined Spaces in Construction, Final Statement of Reasons updated 2025-09-18; effective 2026-01-01", "checked": "2026-11-20", "license": "gov-state", "effective": "2026-01-01", "confidence": "medium"}$kb$::jsonb::text);
  get diagnostics vk = row_count; if vk <> 1 then raise exception 'FAIL: row % is not the expected live text', 3222; end if;
  -- ord 3223: sp-mi-confined-2 (edited in place)
  update pb_ai.kb_chunks set lib = 'field', chunk = $kb${"id": "sp-mi-confined-2", "state": "MI", "tier": "core", "supersedes": "sp-mi-confined-2", "title": "Michigan confined space in construction: MIOSHA Part 35 adopts the federal rule", "topic": "State safety plan: confined space", "text": "Michigan's Construction Safety Standard Part 35, Confined Space in Construction, adopts 29 CFR 1926.1202 (definitions) through 1926.1212 (employee participation) by reference, except as amended in the rules (R 408.43510, via the scope rule R 408.43501(4)). That includes the federal permit items in 1926.1206, so a federal-style entry permit covers Michigan. Part 35 does not apply to work covered by Part 9 (excavation, trenching and shoring), Part 14 (tunnels, shafts, caissons, cofferdams), Part 504 (diving) or Part 665 (underground construction and compressed air); where another standard also covers a confined space hazard, both apply (R 408.43501(2), (3)). Part 35 has three rules: scope, provision of documents, and adopted standards. Work that is not construction (an owner's plant or utility staff) falls under MIOSHA's general industry rule, which MIOSHA lists as Part 90, Permit-Required Confined Spaces (read 2026-11-21; its text was not read here).", "source": "Mich. Admin. Code R 408.43501, R 408.43505, R 408.43510 (MIOSHA Part 35); MIOSHA confined spaces page", "url": "https://www.law.cornell.edu/regulations/michigan/Mich-Admin-Code-R-408-43501", "checked": "2026-11-21", "edition": "Part 35 as posted by Cornell LII, read 2026-11-20; MIOSHA page read 2026-11-21", "confidence": "medium", "kind": "summary", "license": "gov-state", "note": "Adds the Part 90 pointer (MIOSHA page read 2026-11-21)."}$kb$::jsonb
   where version = 'b3e91f6c47d2' and ord = 3223 and chunk->>'id' = $kb$sp-mi-confined-2$kb$ and md5(chunk::text) = md5($kb${"id": "sp-mi-confined-2", "url": "https://www.law.cornell.edu/regulations/michigan/Mich-Admin-Code-R-408-43501", "kind": "summary", "text": "Michigan's Construction Safety Standard Part 35, Confined Space in Construction, adopts 29 CFR 1926.1202 (definitions) through 1926.1212 (employee participation) by reference, except as amended in the rules (R 408.43510, via the scope rule R 408.43501(4)). That includes the federal permit items in 1926.1206, so a federal-style entry permit covers Michigan. Part 35 does not apply to work covered by Part 9 (excavation, trenching and shoring), Part 14 (tunnels, shafts, caissons, cofferdams), Part 504 (diving) or Part 665 (underground construction and compressed air); where another standard also covers a confined space hazard, both apply (R 408.43501(2), (3)). Part 35 has three rules: scope, provision of documents, and adopted standards.", "tier": "core", "state": "MI", "title": "Michigan confined space in construction: MIOSHA Part 35 adopts the federal rule", "topic": "State safety plan: confined space", "source": "Mich. Admin. Code R 408.43501, R 408.43505, R 408.43510 (MIOSHA Part 35)", "checked": "2026-11-20", "edition": "Part 35 as posted by Cornell LII, read 2026-11-20", "license": "gov-state", "confidence": "medium"}$kb$::jsonb::text);
