  -- ord 3224: sp-md-trench-1 (edited in place)
  update pb_ai.kb_chunks set lib = 'field', chunk = $kb${"id": "sp-md-trench-1", "url": "https://labor.maryland.gov/labor/mosh/reqprotect.shtml", "kind": "summary", "text": "Maryland (MOSH) uses the federal excavation rule: a protective system from 5 feet unless the trench is entirely in stable rock (29 CFR 1926.652). Maryland amends 1926.652 on records: the tabulated data used for a protective system, a slope design, the manufacturer's data and any approval to deviate from it, and an engineer's design are kept at the jobsite while the system is being built and after that until it is no longer used; then they may be kept off site but available to the Commissioner of Labor and Industry on request (Maryland amendments to 1926.652(b)(4)(iii), (c)(2)(iii), (c)(4)(iii)). Confined space in construction is the federal rule, 29 CFR 1926 Subpart AA, adopted by reference effective January 2, 2017 (MOSH adoption page, read 2026-11-21).", "tier": "core", "state": "MD", "title": "Maryland trench rule: federal 5 feet, plus protective system records kept at the jobsite", "topic": "State safety plan: trench and excavation", "source": "MOSH, Maryland amendments to 29 CFR 1926.652; MOSH-specific standards list", "checked": "2026-11-20", "edition": "MOSH web pages, read 2026-11-20", "license": "gov-state", "confidence": "medium"}$kb$::jsonb
   where version = 'b3e91f6c47d2' and ord = 3224 and chunk->>'id' = $kb$sp-md-trench-1$kb$ and md5(chunk::text) = md5($kb${"id": "sp-md-trench-1", "url": "https://labor.maryland.gov/labor/mosh/reqprotect.shtml", "kind": "summary", "text": "Maryland (MOSH) uses the federal excavation rule: a protective system from 5 feet unless the trench is entirely in stable rock (29 CFR 1926.652). Maryland amends 1926.652 on records: the tabulated data used for a protective system, a slope design, the manufacturer's data and any approval to deviate from it, and an engineer's design are kept at the jobsite while the system is being built and after that until it is no longer used; then they may be kept off site but available to the Commissioner of Labor and Industry on request (Maryland amendments to 1926.652(b)(4)(iii), (c)(2)(iii), (c)(4)(iii)). MOSH lists no Maryland supplement to the confined space in construction rule.", "tier": "core", "state": "MD", "title": "Maryland trench rule: federal 5 feet, plus protective system records kept at the jobsite", "topic": "State safety plan: trench and excavation", "source": "MOSH, Maryland amendments to 29 CFR 1926.652; MOSH-specific standards list", "checked": "2026-11-20", "edition": "MOSH web pages, read 2026-11-20", "license": "gov-state", "confidence": "medium"}$kb$::jsonb::text);
