  -- 4. new cards
  insert into pb_ai.kb_chunks (version, ord, lib, chunk)
  select 'b3e91f6c47d2', 3233 + t.i, t.e->>'lib', t.e->'chunk' from jsonb_array_elements($kb$[{"lib": "field", "chunk": {"id": "osha-pl-cs-air-1", "state": "US", "tier": "core", "title": "Confined space air limits for manhole and vault entry: oxygen, LEL, hydrogen sulfide (H2S) and carbon monoxide (CO)", "topic": "Confined space rules (OSHA Subpart AA)", "text": "Air limits for a permit space under the construction rule (29 CFR 1926.1202, hazardous atmosphere): oxygen below 19.5 percent is deficient and above 23.5 percent is enriched (a fire hazard); flammable gas, vapor or mist over 10 percent of its lower flammable limit (LFL, also called LEL); combustible dust at or above its LFL; any substance above its OSHA permissible exposure limit; or anything immediately dangerous to life or health. Subpart AA sets no H2S or CO number; the exposure limit tables do: H2S 10 ppm 8-hour average (1926.55 Appendix A), CO 50 ppm (federal construction PEL; NIOSH recommends 35 ppm, which most monitor alarms use). NIOSH IDLH: H2S 100 ppm, CO 1,200 ppm. App permit defaults: O2 19.5 to 23.5 percent, LEL 10 percent, H2S 10 ppm, CO 25 ppm (stricter than federal); a state plan or company program may be stricter. An open excavation uses 20 percent of the LFL (1926.651(g)(1)(iii)); a confined space, 10 percent. These numbers do not by themselves make a space safe: the entry supervisor signs only when testing at all levels, ventilation, attendant, communication, retrieval and rescue are in place.", "source": "29 CFR 1926.1202 (hazardous atmosphere); 1926.651(g)(1)(iii); 1926.55 Appendix A; NIOSH Pocket Guide; app permit defaults r15.95", "url": "https://www.osha.gov/laws-regs/regulations/standardnumber/1926/1926.1202", "checked": "2026-11-20", "edition": "eCFR current text, read 2026-11-20", "confidence": "high", "kind": "summary", "license": "gov-us", "note": "Takes in confined-space-field-numbers-1 (retired). Its state numbers (15 ppm / 50 ppm H2S, 25 ppm CO PEL) are in sp-ca-confined-air-1."}},
{"lib": "field", "chunk": {"id": "osha-pl-cs-permit-keep-1", "state": "US", "tier": "core", "title": "Confined space permit process: sign before entry, post it, cancel or suspend, keep canceled permits 1 year", "topic": "Confined space rules (OSHA Subpart AA)", "text": "29 CFR 1926.1205. The entry employer documents the measures on a permit (a); the entry supervisor named on it signs before entry (b). It is available to entrants at entry, posted at the portal or an equally effective way (c), for no longer than the task needs (d). The supervisor cancels it when the work is done, or suspends or cancels it and fully reassesses before re-entry when a temporary condition not allowed arises; any other such condition means cancel (e). \"The entry employer must retain each canceled entry permit for at least 1 year\", with problems met noted on it so the program can be fixed (f); the program review uses them within 1 year after each entry; one yearly review can cover all (1926.1204(n)). Entry is any body part breaking the plane of the opening (1926.1202): a head in a manhole counts. The app keeps every closed permit in Records. A new condition (alarm, weather, new hazard): out, cancel, re-evaluate.", "source": "29 CFR 1926.1205(a)-(f); 1926.1204(n); 1926.1202 (entry)", "url": "https://www.osha.gov/laws-regs/regulations/standardnumber/1926/1926.1205", "checked": "2026-11-21", "edition": "29 CFR 1926.1205 as in the library's verbatim text (eCFR, read 2026-11-20)", "confidence": "high", "kind": "summary", "license": "gov-us", "note": "Takes in confined-space-field-numbers-4 (retired) and the 1205 sentences of osha-pl-cs-permit-1."}},
{"lib": "field", "chunk": {"id": "osha-pl-cs-retrieval-1", "state": "US", "tier": "core", "title": "Confined space retrieval: harness, line, and a mechanical device for vertical spaces over 5 ft (non-entry rescue)", "topic": "Confined space rules (OSHA Subpart AA)", "text": "29 CFR 1926.1211(c): \"Non-entry rescue is required unless the retrieval equipment would increase the overall risk of entry or would not contribute to the rescue of the entrant.\" Otherwise the employer designates an entry rescue service; with non-entry rescue it confirms before entry that help is available if it fails. Each entrant wears a chest or full body harness, line at the center of the back near shoulder level or above the head (wristlets or anklets only if a harness is infeasible or more hazardous). The other end goes to a mechanical device or fixed point outside, and \"A mechanical device must be available to retrieve personnel from vertical type permit spaces more than 5 feet (1.52 meters) deep\": a tripod and winch or davit, so every manhole and most vaults. No lines that could tangle. The attendant stays outside and does non-entry rescue only (1926.1209(d), (i)); a trained team does entry rescue. No retrieval set up, no entry.", "source": "29 CFR 1926.1211(c)(1)-(3); 1926.1209(d), (i), (j)", "url": "https://www.osha.gov/laws-regs/regulations/standardnumber/1926/1926.1211", "checked": "2026-11-21", "edition": "29 CFR 1926.1211 as in the library's verbatim text (eCFR, read 2026-11-20)", "confidence": "high", "kind": "summary", "license": "gov-us", "note": "Takes in confined-space-field-numbers-3 (retired) and the retrieval half of osha-pl-cs-rescue-1."}},
{"lib": "field", "chunk": {"id": "osha-pl-cs-reclass-1", "state": "US", "tier": "core", "title": "Reclassifying a permit space as non-permit (and back): what the competent person must find and write down", "topic": "Confined space rules (OSHA Subpart AA)", "text": "29 CFR 1926.1203(g): a permit space may be reclassified as a non-permit confined space only when a competent person determines that the space has no actual or potential atmospheric hazard and every hazard in it is eliminated or isolated without entry (unless that is shown infeasible), and only while they stay that way. An entry needed to eliminate or isolate them is a full permit entry. Forced air ventilation does not count as eliminating or isolating a hazard (ventilation-only entry is 1203(e), not a reclassification). The basis is documented in a certification with the date, the location of the space and the signature of the person deciding, available to each entrant (g)(3). If hazards arise, everyone exits and the space is re-evaluated and reclassified as a permit space as needed (g)(4). The other way: when use or configuration changes might increase the hazards, or the first evaluation may have been inadequate, a competent person re-evaluates the non-permit space and reclassifies it if necessary (1203(f)).", "source": "29 CFR 1926.1203(f), (g)(1)-(4)", "url": "https://www.ecfr.gov/current/title-29/subtitle-B/chapter-XVII/part-1926/subpart-AA", "checked": "2026-11-21", "edition": "29 CFR 1926.1203 as in the library's verbatim text (eCFR, read 2026-11-20)", "confidence": "high", "kind": "summary", "license": "gov-us", "note": "New: reclassification on its own card (was one sentence of osha-pl-cs-altproc-1)."}},
{"lib": "field", "chunk": {"id": "osha-pl-cs-states-1", "state": "US", "tier": "core", "title": "Does my state follow the federal confined space rule? States where federal OSHA's Subpart AA applies to private crews", "topic": "Confined space rules: which states follow federal OSHA", "text": "Where a state has no state OSHA plan for private employers, federal OSHA covers private construction crews and its confined space in construction rule, 29 CFR 1926 Subpart AA, applies with no state difference: the same air limits, the 16 permit items, the attendant, rescue and retrieval rules and the 1 year permit retention. Use only the line for the job's state. Federal rule, no state OSHA plan (OSHA list of State Plans): Alabama, Arkansas, Colorado, Delaware, District of Columbia, Florida, Georgia, Idaho, Kansas, Louisiana, Mississippi, Missouri, Montana, Nebraska, New Hampshire, North Dakota, Ohio, Oklahoma, Pennsylvania, Rhode Island, South Dakota, Texas, West Virginia, Wisconsin. Federal rule for private crews, state plan for public employees only: Connecticut, Illinois, Maine, Massachusetts, New Jersey, New York (a city's or district's own employees on the same job are under the state plan). In these states there is no separate state confined space rule for private crews in the library. The other 21 states run their own plan for private crews (see the state-plan confined space table).", "source": "29 CFR 1926 Subpart AA; OSHA State Plans list (osha.gov/stateplans), read 2026-11-20", "url": "https://www.osha.gov/stateplans", "checked": "2026-11-21", "edition": "29 CFR 1926 Subpart AA as in effect Nov 2026; OSHA State Plans list read 2026-11-20", "confidence": "medium", "kind": "summary", "license": "gov-us"}},
{"lib": "field", "chunk": {"id": "osha-pl-cs-states-2", "state": "US", "tier": "core", "title": "State OSHA plans and confined space: which plan states use federal Subpart AA, which have their own rule", "topic": "Confined space rules: which states follow federal OSHA", "text": "Twenty-one states run their own OSHA plan for private construction crews. A plan must be at least as effective as federal OSHA's confined space in construction rule (29 CFR 1926 Subpart AA) and may be stricter, so name the plan as the source. Use only the line for the job's state. As checked by 2026-11-21. Uses the federal rule: Alaska (8 AAC 61.1010(c)), Maryland (by reference from January 2, 2017; a MOSH supplement is listed, text not read, not confirmed), Michigan (Part 35, except as amended), Minnesota (old state rule repealed), New Mexico, Tennessee, Utah, Virginia (from January 1, 2016). Not on the plan's unique list, so taken as federal: Arizona, Nevada, North Carolina, Hawaii (not confirmed). Own rule, each has its own card: California (8 CCR 1950 to 1962, amended January 1, 2026, stricter CO limit), Washington (chapter 296-809, all industries), Oregon (437-002-0146; supervisor signs, not initials). Not checked: Indiana, Kentucky, South Carolina, Iowa, Vermont, Wyoming: federal Subpart AA is the floor; ask the state plan.", "source": "osha.gov/stateplans; 8 AAC 61.1010(c); MIOSHA Part 35 R 408.43510; Minn. R. 5207.0300 (repealed); MOSH Subpart AA adoption page; each state card", "url": "https://www.osha.gov/stateplans", "checked": "2026-11-21", "edition": "State plan rules as read 2026-11-19 to 2026-11-21", "confidence": "medium", "kind": "summary", "license": "gov-us", "unconfirmed": "yes", "note": "Built from the sp-<st>-who-1 / sp-<st>-confined-* cards; Maryland from the MOSH adoption page read 2026-11-21."}}]$kb$::jsonb) with ordinality t(e, i);
  get diagnostics vk = row_count; if vk <> 6 then raise exception 'FAIL: inserted % rows', vk; end if;

  -- 5. row count for the loader, drop the saved index
  update pb_ai.kb_versions v set n = c.n, counts = c.counts
    from (select sum(k)::int as n, jsonb_object_agg(lib, k) as counts from (select lib, count(*)::int as k from pb_ai.kb_chunks where version = 'b3e91f6c47d2' group by lib) x) c
   where v.version = 'b3e91f6c47d2';
  delete from pb_ai.kb_index_parts where version = 'b3e91f6c47d2';   -- the saved search index is rebuilt by the next cold start (about 2 s, once)
  delete from pb_ai.kb_index where version = 'b3e91f6c47d2';

  -- 6. checks
  select count(*), max(ord), count(distinct chunk->>'id') into vn, vmx, vd from pb_ai.kb_chunks where version = 'b3e91f6c47d2';
  if vn <> 3240 or vmx <> 3239 then raise exception 'FAIL ord gap or count: % rows, max ord %', vn, vmx; end if;
  if vd <> vn then raise exception 'FAIL duplicate chunk id'; end if;
  if (select v.n from pb_ai.kb_versions v where v.version = 'b3e91f6c47d2') <> 3240 then raise exception 'FAIL kb_versions.n'; end if;
  if (select md5(string_agg(ord||':'||lib||':'||(chunk::text), '|' order by ord)) from pb_ai.kb_chunks where version = 'b3e91f6c47d2') <> '131904c2de6b687c14ff4d68ccaea531' then raise exception 'FAIL: result differs from the tested library'; end if;
  raise notice 'consolidate_cs 21_load: applied, % rows', vn;
end $load$;
commit;
